from layout import *
def trace():
    page('Короткая память о прошлых действиях','Достаточно ли передать путь и номера строк',
         'На SERBench адреса оказались полезнее сырого конца истории. Преимущество над самым сильным ограниченным контролем пока лежит в пределах статистической неопределённости.')
    p('Состояние читателя включает постановку задачи, текущую потребность в информации и подцель. Отправителю доступны только предыдущие вызовы инструментов и их ответы. Он выписывает пути и диапазоны строк, упомянутые при чтении, и короткие аргументы действий, пока сообщение помещается в 192 токена. Пула объектов и разметки отправитель не видит. Принимающая сторона учится ранжировать объекты на других репозиториях по одной и той же схеме признаков для всех вариантов.')
    t=J('serbench/trace_results.json')['arms']
    order=[('Без сообщения','empty'),('Начало истории','head'),('Конец истории','tail'),('Равномерные выдержки','uniform'),('Аргументы вызовов','arguments'),('Пути, строки и аргументы','addresses'),('Вся история','complete')]
    tbl(['Содержимое записи','Средний размер, токенов','Полнота @5','Полнота @8'],[[name,dec(t[k]['mean_tokens'],1),perc(t[k]['mean']['mss_complete@5']),perc(t[k]['mean']['mss_complete@8'])] for name,k in order],[6.4,4.0,3.35,3.35],True)
    p('При пяти объектах адресная запись восстановила все требования в 122 из 500 состояний. Аргументы без адресов — в 108. Разность +2,8 п.п., 95% ДИ по репозиториям от −1,05 до +6,60. Длинная история эквивалентна в среднем 4 864 токенам и даёт 114 полных ответов из 500. Результат относится к обученному лексическому читателю, способному использовать пути и номера строк.')
    p('Этот вариант разработан после просмотра основной таблицы Cal500. Машинная разметка калибровочной части и отсутствие наблюдавшихся ID кандидатов во всех 500 её состояниях ограничивают перенос. В Test500 ненулевые списки таких ID встречаются в 298 состояниях. Проверка на полностью отложенной части требует скрытой оценки.')
    p('Здесь 192 токена — сообщение из истории для ранжировщика. В основной статье SERBench предел 6 144 относится к объёму возвращаемых фрагментов. Пересчёт по токенизатору Qwen дал в среднем 3 246 токенов кода для восьми объектов парной модели на Cal500. Жёсткий лимит сохранил все результаты Cal500 и изменил 9 из 500 списков Test500. Новые предсказания занимают максимум 6 143 токена, их скрытая точность неизвестна.')
    source('Формат задач и процедура оцeнки · SERBench','https://github.com/LordTARN1SHED/SERBench/tree/8c27a88e48dcbcd4a5745573c95937a4740f4406')
